import numpy as np
from PIL import Image
a = np.array(Image.open('../mol_0154.png').convert('L')) < 128

def widths_vertical(x0,x1,y0,y1):
    out=[]
    for y in range(y0,y1):
        xs = np.where(a[y, x0:x1])[0]
        if len(xs): out.append((y, xs.min()+x0, xs.max()+x0, len(xs)))
    return out

